CREATE TABLE IF NOT EXISTS public.bbj_payout_recipients(id uuid NOT NULL,payout_id uuid NOT NULL,user_id uuid NOT NULL,amount numeric NOT NULL,created_at timestamptz NOT NULL,PRIMARY KEY(id));
CREATE TABLE IF NOT EXISTS public.bbj_payouts(id uuid NOT NULL,pool_id uuid NOT NULL,hand_id uuid,table_id uuid NOT NULL,hand_number int8,winner_user_id uuid NOT NULL,loser_user_id uuid NOT NULL,total_amount numeric NOT NULL,winner_share numeric NOT NULL,loser_share numeric NOT NULL,table_share numeric NOT NULL,table_player_count int4 NOT NULL,metadata jsonb,created_at timestamptz NOT NULL,kind text NOT NULL,PRIMARY KEY(id));
CREATE TABLE IF NOT EXISTS public.bbj_pools(id uuid NOT NULL,club_id uuid,union_id uuid,pool_amount numeric NOT NULL,hands_contributed int8,last_hit_at timestamptz,last_hit_amount numeric,last_winner_id uuid,created_at timestamptz,updated_at timestamptz,main_balance numeric NOT NULL,backup_balance numeric NOT NULL,promo_balance numeric NOT NULL,status text NOT NULL,total_contributed numeric,total_paid_out numeric NOT NULL,hit_count int4 NOT NULL,last_loser_id uuid,merged_into_pool_id uuid,alloc_cum_amount numeric NOT NULL,mini_reserve_floor numeric NOT NULL,mini_enabled bool NOT NULL,PRIMARY KEY(id));
CREATE TABLE IF NOT EXISTS public.bbj_unclaimed_shares(id uuid NOT NULL,payout_id uuid NOT NULL,pool_id uuid,table_id uuid,user_id uuid NOT NULL,amount numeric NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL,paid_at timestamptz,paid_note text,PRIMARY KEY(id));
CREATE TABLE IF NOT EXISTS public.chip_transactions(id uuid NOT NULL,club_id uuid NOT NULL,from_user_id uuid,to_user_id uuid,amount numeric NOT NULL,transaction_type text NOT NULL,notes text,related_cashout_id uuid,metadata jsonb,created_at timestamptz,balance_after numeric,clawed_back bool,reversible_until timestamptz,is_reversed bool,table_id uuid,PRIMARY KEY(id));
CREATE TABLE IF NOT EXISTS public.wallet_credit_idempotency(key text NOT NULL,user_id uuid,amount numeric,created_at timestamptz NOT NULL,PRIMARY KEY(key));
CREATE TABLE IF NOT EXISTS public.union_pnl_cash_outcomes(table_id uuid,hand_number bigint,hand_id uuid,transaction_id xid8,recognized_at timestamptz,payload_hash text,game_scope jsonb,evidence jsonb,PRIMARY KEY(table_id,hand_number));
